PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE IF NOT EXISTS "backend_order" ("order_id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "order_number" integer NOT NULL, "order_date" datetime NOT NULL, "expected_date" date NOT NULL, "order_status" varchar(30) NOT NULL, "order_quantity" integer NOT NULL, "order_total_price" decimal NOT NULL);
CREATE TABLE IF NOT EXISTS "backend_category" ("category_id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "category_description" varchar(100) NOT NULL, "category_name" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "backend_unit" ("unit_id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "unit_of_measurement" varchar(100) NOT NULL, "unit_measurement_symbol" varchar(5) NOT NULL);
CREATE TABLE IF NOT EXISTS "backend_supplier" ("supplier_id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "supplier_name" varchar(50) NOT NULL, "supplier_title" varchar(10) NOT NULL, "supplier_location" text NOT NULL, "supplier_number" integer NOT NULL, "supplier_link" text NOT NULL, "supplier_rating" integer NOT NULL, "supplier_media" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "backend_expenses" ("expense_date" datetime NOT NULL, "expense_id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "expense_detail" varchar(20) NOT NULL, "expense_amount" integer NOT NULL);
CREATE TABLE IF NOT EXISTS "backend_salesitem" ("saleItem_id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "product_quantity" integer NOT NULL, "product_totalCost" integer NOT NULL, "product_id_id" integer NOT NULL REFERENCES "backend_product" ("product_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "backend_orderitem" ("order_item_id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "product_quantity" integer NOT NULL, "unit_price" decimal NOT NULL, "total_price" decimal NOT NULL, "product_id" integer NOT NULL REFERENCES "backend_product" ("product_id") DEFERRABLE INITIALLY DEFERRED, "order_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "backend_stock" ("stock_id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "stock_amount" integer NOT NULL, "product_id_id" integer NOT NULL REFERENCES "backend_product" ("product_id") DEFERRABLE INITIALLY DEFERRED, "stock_changed_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "backend_transactions" ("transaction_id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "transaction_amount" integer NOT NULL, "transaction_type" text NOT NULL, "order_id_id" integer NULL REFERENCES "backend_orderitem" ("order_item_id") DEFERRABLE INITIALLY DEFERRED, "product_id_id" integer NOT NULL REFERENCES "backend_product" ("product_id") DEFERRABLE INITIALLY DEFERRED, "transaction_payment_method" varchar(10) NOT NULL, "transaction_receipt_id" varchar(10) NOT NULL UNIQUE, "transaction_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "backend_manufacturer" ("manufacturer_id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "manufacturer_name" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "backend_product" ("product_id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "product_name" varchar(100) NOT NULL, "product_description" text NOT NULL, "product_cost" decimal NOT NULL, "product_price" decimal NOT NULL, "category_id_id" integer NOT NULL REFERENCES "backend_category" ("category_id") DEFERRABLE INITIALLY DEFERRED, "unit_id_id" integer NOT NULL REFERENCES "backend_unit" ("unit_id") DEFERRABLE INITIALLY DEFERRED, "product_photo" varchar(100) NOT NULL, "product_manufacturer_id" integer NULL REFERENCES "backend_manufacturer" ("manufacturer_id") DEFERRABLE INITIALLY DEFERRED);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "auth_group_permissions_group_id_permission_id_0cd325b0_uniq" ON "auth_group_permissions" ("group_id", "permission_id");
CREATE INDEX "auth_group_permissions_group_id_b120cbf9" ON "auth_group_permissions" ("group_id");
CREATE INDEX "auth_group_permissions_permission_id_84c5c92e" ON "auth_group_permissions" ("permission_id");
CREATE UNIQUE INDEX "auth_user_groups_user_id_group_id_94350c0c_uniq" ON "auth_user_groups" ("user_id", "group_id");
CREATE INDEX "auth_user_groups_user_id_6a12ed8b" ON "auth_user_groups" ("user_id");
CREATE INDEX "auth_user_groups_group_id_97559544" ON "auth_user_groups" ("group_id");
CREATE UNIQUE INDEX "auth_user_user_permissions_user_id_permission_id_14a6b632_uniq" ON "auth_user_user_permissions" ("user_id", "permission_id");
CREATE INDEX "auth_user_user_permissions_user_id_a95ead1b" ON "auth_user_user_permissions" ("user_id");
CREATE INDEX "auth_user_user_permissions_permission_id_1fbb5f2c" ON "auth_user_user_permissions" ("permission_id");
CREATE INDEX "django_admin_log_content_type_id_c4bce8eb" ON "django_admin_log" ("content_type_id");
CREATE INDEX "django_admin_log_user_id_c564eba6" ON "django_admin_log" ("user_id");
CREATE UNIQUE INDEX "django_content_type_app_label_model_76bd3d3b_uniq" ON "django_content_type" ("app_label", "model");
CREATE UNIQUE INDEX "auth_permission_content_type_id_codename_01ab375a_uniq" ON "auth_permission" ("content_type_id", "codename");
CREATE INDEX "auth_permission_content_type_id_2f476e4b" ON "auth_permission" ("content_type_id");
CREATE INDEX "backend_salesitem_product_id_id_cc8d5339" ON "backend_salesitem" ("product_id_id");
CREATE INDEX "backend_orderitem_product_id_b45f2dc0" ON "backend_orderitem" ("product_id");
CREATE INDEX "backend_stock_product_id_id_4fbbfeb6" ON "backend_stock" ("product_id_id");
CREATE INDEX "backend_transactions_order_id_id_2461c430" ON "backend_transactions" ("order_id_id");
CREATE INDEX "backend_transactions_product_id_id_19a1727c" ON "backend_transactions" ("product_id_id");
CREATE INDEX "django_session_expire_date_a5c62663" ON "django_session" ("expire_date");
CREATE INDEX "backend_product_category_id_id_13aacd9b" ON "backend_product" ("category_id_id");
CREATE INDEX "backend_product_unit_id_id_f487aeac" ON "backend_product" ("unit_id_id");
CREATE INDEX "backend_product_product_manufacturer_id_918177b5" ON "backend_product" ("product_manufacturer_id");
COMMIT;
